function escapeHtml(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function inlineMd(s){
  s=escapeHtml(s);
  s=s.replace(/`([^`]+)`/g, function(_,c){ return '<code>'+c+'</code>'; });
  s=s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  s=s.replace(/\*([^*]+)\*/g, '<em>$1</em>');
  s=s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2">$1</a>');
  return s;
}
function mdToHtml(md){
  var lines=String(md||'').split(/\r?\n/);
  var out=[], i=0;
  while(i<lines.length){
    var ln=lines[i];
    if(/^```/.test(ln)){
      var code=[]; i++;
      while(i<lines.length && !/^```/.test(lines[i])){ code.push(lines[i]); i++; }
      i++;
      out.push('<pre><code>'+escapeHtml(code.join('\n'))+'</code></pre>');
      continue;
    }
    var h=ln.match(/^(#{1,6})\s+(.*)$/);
    if(h){ var l=h[1].length; out.push('<h'+l+'>'+inlineMd(h[2])+'</h'+l+'>'); i++; continue; }
    if(/^(?:---+|\*\*\*+)\s*$/.test(ln)){ out.push('<hr>'); i++; continue; }
    if(/^>\s?/.test(ln)){
      var bq=[];
      while(i<lines.length && /^>\s?/.test(lines[i])){ bq.push(lines[i].replace(/^>\s?/,'')); i++; }
      out.push('<blockquote>'+inlineMd(bq.join(' '))+'</blockquote>');
      continue;
    }
    if(/^[-*+]\s+/.test(ln)){
      var ul=[];
      while(i<lines.length && /^[-*+]\s+/.test(lines[i])){ ul.push('<li>'+inlineMd(lines[i].replace(/^[-*+]\s+/,''))+'</li>'); i++; }
      out.push('<ul>'+ul.join('')+'</ul>');
      continue;
    }
    if(/^\d+\.\s+/.test(ln)){
      var ol=[];
      while(i<lines.length && /^\d+\.\s+/.test(lines[i])){ ol.push('<li>'+inlineMd(lines[i].replace(/^\d+\.\s+/,''))+'</li>'); i++; }
      out.push('<ol>'+ol.join('')+'</ol>');
      continue;
    }
    if(!ln.trim()){ i++; continue; }
    var p=[ln];
    i++;
    while(i<lines.length && lines[i].trim() && !/^(#{1,6}\s|>|[-*+]\s|\d+\.\s|```|---)/.test(lines[i])){ p.push(lines[i]); i++; }
    out.push('<p>'+inlineMd(p.join(' '))+'</p>');
  }
  return out.join('\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { mdToHtml:mdToHtml, inlineMd:inlineMd, escapeHtml:escapeHtml };
}
if (typeof window !== 'undefined') {
  window.MarkdownForgePure = { mdToHtml:mdToHtml, inlineMd:inlineMd, escapeHtml:escapeHtml };
}
